  /// Add templates for a specific theme
  static void _addTemplates(String theme, List<TriviaTemplate> templates) {
    if (!_templatesByTheme.containsKey(theme)) {
      _templatesByTheme[theme] = <TriviaTemplate>[];
    }
    _templatesByTheme[theme]!.addAll(templates);
  }

  /// Get all available themes
  static List<String> getAvailableThemes() {
    return _templatesByTheme.keys.toList();
  }

  /// Get templates for a specific theme
  static List<TriviaTemplate> getTemplatesForTheme(String theme) {
    return _templatesByTheme[theme] ?? <TriviaTemplate>[];
  }

  /// Map editions to themes
  static void _mapEditionsToThemes() {
    _editionThemeMapping.clear();
    // Basic mapping: each theme maps to itself as an edition
    for (final theme in _templatesByTheme.keys) {
      _editionThemeMapping[theme] = [theme];
    }
  }
